mapper.select:
SELECT t.*, r.id as receive_id, r.send_id, r.ENTRUSTED_MIX_AREA, r.machine_code as receive_machine_code
FROM T_GLUE_DECOMPOSE_PLAN t
LEFT JOIN T_GLUE_SPAN_RECEIVE r on t.mix_area = r.ENTRUST_MIX_AREA and t.plan_date = r.schedule_date
                                   and t.glue = r.glue and r.del_flag='0'
                                   and r.id in #{receiveId}
where plan_date = #{planDate}
 and mix_area = #{mixArea}
 and t.del_flag='0'
 and t.final_glue_machine in (SELECT t1.final_glue_machine
                              FROM T_GLUE_DECOMPOSE_PLAN t1
                              INNER JOIN T_GLUE_SPAN_RECEIVE r1 on t1.id = r1.schedule_id and t1.plan_date=r1.schedule_date
                                                                   and t1.plan_date=#{planDate}
                              WHERE r1.id in #{receiveId}
                              )
order by t.final_glue_machine, (case when instr(t.glue,'/')=0 then 'ZZZ' else t.glue end) desc

