AND PLAN_DATE = #{planDate}
AND mix_area = #{mixArea}
and (UP_GLUE = #{upGlue}
         or UP_GLUE like concat(#{upGlue}, ',%')
         or UP_GLUE like concat('%,', #{upGlue})
         or UP_GLUE like concat('%,', #{upGlue}, ',%'))

